func cardsForGame(gameID, kind string) []Card {
	if kind == "mission" && gameID == "escape" {
		return missionCards
	}
	var cards []Card
	switch gameID {
	case "anatomy":
		cards = anatomyCards
	case "classify":
		cards = classifyCards
	case "surgery":
		cards = surgeryCards
	case "creator":
		cards = creatorCards
	default:
		cards = questionCards
	}
	filtered := make([]Card, 0, len(cards))
	for _, card := range cards {
		if card.Kind == kind && !card.Open && card.Answer != "" && len(card.Choices) > 0 {
			filtered = append(filtered, card)
		}
	}
	if len(filtered) > 0 {
		return filtered
	}
	return cards
}

func cellType(position int) string {
	questions := map[int]bool{1: true, 6: true, 10: true, 15: true, 21: true}
	missions := map[int]bool{4: true, 7: true, 13: true, 18: true}
	bonuses := map[int]bool{3: true, 8: true, 16: true, 22: true}
	backs := map[int]bool{11: true, 20: true}
	switch {
	case questions[position]:
		return "question"
	case missions[position]:
		return "mission"
	case bonuses[position]:
		return "bonus"
	case backs[position]:
		return "back"
	}
	return "plain"
}
